INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(23301, 'Mark 6:13', 'Mark', 6, 13, '&nbsp;هغوئ ډېر پيريان وشړل او ډېر بيماران يې په تېلو مسح کړل او ډېرو خلقو له يې شفا ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23302, 'Mark 6:14', 'Mark', 6, 14, '&nbsp;نو هيروديس بادشاه د دې نه خبر شو ځکه چې د عيسىٰ نامه مشهوره شوه. ځينې خلقو دا وئيل چې، ”بپتسمه ورکوونکے يحيىٰ بيا د مرو نه راژوندے شوے دے، ځکه خو ورسره د معجزو طاقت هم دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23303, 'Mark 6:15', 'Mark', 6, 15, '&nbsp;خو نورو وئيل چې، ”دا الياس دے.“ او ځينو وئيل چې، ”دا د پخوانو نبيانو په شان لوئ نبى دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23304, 'Mark 6:16', 'Mark', 6, 16, '&nbsp;خو چې هيروديس د عيسىٰ په حقله واورېدل نو وې وئيل چې، ”هغه يحيىٰ چې ما يې سر پرې کړے وو بيا راژوندے شوے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23305, 'Mark 6:17', 'Mark', 6, 17, '&nbsp;ځکه هيروديس د خپل ورور فيليپوس د ښځې هيرودياس په وجه يحيىٰ ګرفتار کړے وو، په زنځير يې تړلے وو او په قېدخانه کښې يې اچولے وو. ځکه چې هيروديس بادشاه اوس پخپله د هيرودياس سره وادۀ کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23306, 'Mark 6:18', 'Mark', 6, 18, '&nbsp;او يحيىٰ هغۀ ته فرمائيلى وُو چې، ”د خپل ورور د ښځې سره نِکاح کول په تا حرام دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23307, 'Mark 6:19', 'Mark', 6, 19, '&nbsp;نو په دې وجه د هغۀ ښځې هيرودياس ورسره کينه لرله او غوښتل يې چې هغه قتل کړى خو کولے يې نۀ شو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23308, 'Mark 6:20', 'Mark', 6, 20, '&nbsp;ځکه چې هيروديس د يحيىٰ نه په دې يرېدو چې هغۀ ته معلومه وه چې دے پاک او نېک سړے دے، ځکه يې د هغۀ ساتنه وکړه. هيروديس دا غوښتل چې د هغۀ خبرې واورى اګر چې د هغۀ خبرو هغه ډېر وارخطا کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23309, 'Mark 6:21', 'Mark', 6, 21, '&nbsp;خو آخر هيرودياس ته دا موقع مِلاو شوه کله چې هيروديس په خپله سالګره کښې خپلو اميرانو، فوجى آفسرانو او د ګليل لويو خلقو ته مېلمستيا کړې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23310, 'Mark 6:22', 'Mark', 6, 22, '&nbsp;د هغې لور دننه راغله او ګډه شوه او هيروديس او د هغۀ مېلمانۀ دومره خوشحاله شول چې بادشاه جينۍ ته ووئيل، ”څۀ چې غواړې وې غواړه، نو زۀ به يې درکړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23311, 'Mark 6:23', 'Mark', 6, 23, '&nbsp;او هغۀ هغې ته قسم وخوړو، ”هر څۀ چې تۀ غواړې، زۀ به يې درکړم تر خپلې نيمې بادشاهۍ پورې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23312, 'Mark 6:24', 'Mark', 6, 24, '&nbsp;هغه بهر ووتله او خپلې مور ته يې ووئيل چې، ”زۀ ترې څۀ وغواړم؟“ هغې جواب ورکړو، ”د بپتسمه ورکوونکى يحيىٰ سر.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23313, 'Mark 6:25', 'Mark', 6, 25, '&nbsp;جينۍ سمدستى بادشاه له ورغله او خواست يې وکړو، ”زۀ غواړم چې تۀ ما ته اوس دلته د بپتسمه ورکوونکى يحيىٰ سر په تالى کښې راوړې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23314, 'Mark 6:26', 'Mark', 6, 26, '&nbsp;بادشاه ډېر زيات غمژن شو خو د خپلو قسمونو او د مېلمنو په وجه يې دا نۀ غوښتل چې د هغې د خواست نه اِنکار وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23315, 'Mark 6:27', 'Mark', 6, 27, '&nbsp;نو بادشاه سمدستى سپاهى له حُکم ورکړو چې، ”لاړ شه، د يحيىٰ سر راوړه.“ سپاهى لاړو په قېدخانه کښې يې د هغۀ سر پرې کړو', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23316, 'Mark 6:28', 'Mark', 6, 28, '&nbsp;او په يو تالى کښې يې راوړو او جينۍ ته يې پېش کړو، او بيا هغې خپلې مور له ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23317, 'Mark 6:29', 'Mark', 6, 29, '&nbsp;کله چې د يحيىٰ مريدان د دې نه خبر شول نو راغلل د هغۀ لاش يې واخستو او په قبر کښې يې کېښودو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23318, 'Mark 6:30', 'Mark', 6, 30, '&nbsp;رسولان بيا عيسىٰ ته راټول شول او هر څۀ چې يې کړى او ښودلى وُو هغه يې ترې خبر کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23319, 'Mark 6:31', 'Mark', 6, 31, '&nbsp;هغۀ هغوئ ته وفرمائيل چې، ”تاسو ما پسې راځئ چې چرته خوشى بيابان ته لاړ شُو چې تاسو لږ آرام وکړئ.“ ځکه چې دومره زيات خلق تلل راتلل چې هغوئ روټۍ خوړلو ته هم نۀ وزګارېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23320, 'Mark 6:32', 'Mark', 6, 32, '&nbsp;بيا هغوئ په کشتۍ کښې کښېناستل او يو خوشى بيابان ته لاړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23321, 'Mark 6:33', 'Mark', 6, 33, '&nbsp;خو ډېرو خلقو هغوئ په تلو کښې وليدل او وې پېژندل او بيا هغوئ د ټولو ښاريو نه هغه ځائ ته پياده لاړل او د هغوئ نه وړاندې ورسېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23322, 'Mark 6:34', 'Mark', 6, 34, '&nbsp;هغه چې غاړې ته راورسېدو نو يوه لويه ګڼه يې وليده او زړۀ يې پرې وسوزېدلو ځکه چې هغوئ د داسې ګډو په شان وُو چې شپون ورسره نۀ وى او هغۀ هغوئ ته د ډېرو خبرو په حقله تعليم ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23323, 'Mark 6:35', 'Mark', 6, 35, '&nbsp;هر کله چې ورځ په تېرېدو شوه د هغۀ مريدان هغۀ له ورغلل او وې وئيل چې، ”دا خوشے بيابان دے او ناوخته دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23324, 'Mark 6:36', 'Mark', 6, 36, '&nbsp;دا خلق خوا او شا کلو او بانډو ته رُخصت کړه چې لاړ شى خپل ځان له د خوراک څۀ څيزونه واخلى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23325, 'Mark 6:37', 'Mark', 6, 37, '&nbsp;خو هغۀ ورته وفرمائيل چې، ”تاسو د ځانه دوئ له د خوراک څۀ ورکړئ چې وې خورى.“ هغوئ جواب ورکړو، ”ولې مونږ لاړ شُو او د دوو سوو دينارو روټۍ د دوئ د خوړلو دپاره واخلو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23326, 'Mark 6:38', 'Mark', 6, 38, '&nbsp;هغۀ ورته وفرمائيل چې، ”تاسو سره څومره روټۍ دى؟ لاړ شئ او وې ګورئ.“ هغوئ لاړل، وې کتلې او هغۀ ته يې ووئيل چې، ”پينځۀ روټۍ او دوه کبان دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23327, 'Mark 6:39', 'Mark', 6, 39, '&nbsp;بيا هغۀ هغوئ ته حکم ورکړو چې، ”په شين کبل د دې خلقو پېنډه جوړه کړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23328, 'Mark 6:40', 'Mark', 6, 40, '&nbsp;نو هغوئ د پنځوسو او سلو کسانو په پېنډو کښې کښېناستل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23329, 'Mark 6:41', 'Mark', 6, 41, '&nbsp;بيا هغۀ پينځۀ روټۍ او دوه کبان واخستل، آسمان ته يې پاس وکتل، برکت يې ورکړو او روټۍ يې ماتې کړې. او هغه يې مريدانو له ورکړې چې د خلقو په وړاندې کېږدى. او هغۀ هم هغه دوه کبان په هغوئ ټولو تقسيم کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23330, 'Mark 6:42', 'Mark', 6, 42, '&nbsp;هغوئ ټولو ښۀ په مړه ګېډه خوراک وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23331, 'Mark 6:43', 'Mark', 6, 43, '&nbsp;او مريدانو د پاتې شوو روټو او کبانو نه دولس ډکې ټوکرۍ راټولې کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23332, 'Mark 6:44', 'Mark', 6, 44, '&nbsp;نو دا روټۍ څۀ پينځۀ زره سړو وخوړله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23333, 'Mark 6:45', 'Mark', 6, 45, '&nbsp;بيا سمدستى عيسىٰ خپل مريدان کشتۍ ته وخېژول چې د هغوئ نه وړاندې د درياب پورې غاړې بيتِ‌صيدا ته لاړ شى، نو چې هغه په خپله د خلقو ګڼه رُخصت کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23334, 'Mark 6:46', 'Mark', 6, 46, '&nbsp;چې هغوئ يې رُخصت کړل نو په خپله غرۀ ته وختلو چې دُعا وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23335, 'Mark 6:47', 'Mark', 6, 47, '&nbsp;کله چې ماښام ناوخته شو او کِشتۍ په اوبو کښې وړاندې تلې وه او هغه په اوچه کښې بلکل ځان له وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23336, 'Mark 6:48', 'Mark', 6, 48, '&nbsp;عيسىٰ وليدل چې هغوئ د کشتۍ په بوتلو کښې په تکليف دى ځکه چې هوا د مخالف طرف نه وه. او عيسىٰ په شپه کښې د سحر کېدو نه لږ وړاندې د اوبو دپاسه د هغوئ په طرف ورروان وو. نو هغه په هغوئ اوړېدو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23337, 'Mark 6:49', 'Mark', 6, 49, '&nbsp;خو کله چې هغوئ عيسىٰ د اوبو دپاسه روان وليدو، نو دا سوچ يې وکړو چې ګنې دا پيرے دے او چغې يې کړې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23338, 'Mark 6:50', 'Mark', 6, 50, '&nbsp;ځکه چې هغوئ ټولو دے وليدلو او يرې واخستل. خو هغۀ سمدستى وفرمائيل چې، ”مۀ يرېږئ. دا زۀ يم چې يره ونۀ کړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23339, 'Mark 6:51', 'Mark', 6, 51, '&nbsp;بيا هغه د هغوئ سره کِشتۍ ته وختلو او طوفان ودرېدلو. په دې هغوئ بلکل اريان دريان شول،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23340, 'Mark 6:52', 'Mark', 6, 52, '&nbsp;ځکه چې هغوئ لا د روټۍ په هغه واقعه پوهه نۀ وُو، د هغوئ زړونه سخت شوى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23341, 'Mark 6:53', 'Mark', 6, 53, '&nbsp;کله چې هغوئ پورې غاړې ته ورسېدل نو هغوئ د ګِنيسرت علاقې ته راغلل او هلته يې کِشتۍ په ګودر وتړله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23342, 'Mark 6:54', 'Mark', 6, 54, '&nbsp;کله چې هغوئ د کشتۍ نه راکوز شول نو خلقو سمدستى عيسىٰ وپېژندو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23343, 'Mark 6:55', 'Mark', 6, 55, '&nbsp;او خلق ګېرچاپېره علاقې ته په منډه لاړل او د هرې خوا نه يې بيماران په پوزَکو کښې ورته راوړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23344, 'Mark 6:56', 'Mark', 6, 56, '&nbsp;او هر چرته چې به هغه تلو، کلو، ښارونو، يا بانډو ته، هغوئ به په بازارونو کښې ورته بيماران کښېنول او هغۀ ته يې مِنت وکړو چې دوئ له دومره اجازت ورکړه چې ستا لمنې له لاس وروړى، او هر چا چې لاس وروړو، هغه بلکل روغ شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23345, 'Mark 7:1', 'Mark', 7, 1, '&nbsp;فريسيان او ځينې د شرعې عالمان د يروشلم نه عيسىٰ له راغلل او هغۀ ته راټول شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23346, 'Mark 7:2', 'Mark', 7, 2, '&nbsp;نو هغوئ وليدل چې د هغۀ مريدان په ناوينځلو لاسونو روټۍ خورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23347, 'Mark 7:3', 'Mark', 7, 3, '&nbsp;ځکه چې فريسيان او ټول يهوديان د خپلو مشرانو د رواياتو په مطابق هيڅکله هم په ناوينځلو لاسونو روټۍ نۀ خورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23348, 'Mark 7:4', 'Mark', 7, 4, '&nbsp;کله چې هغوئ د بازار نه راشى تر هغې خوراک نۀ کوى ترڅو چې يې غسل نۀ وى کړے، او ډېر نور داسې رِواجونه دى چې هغوئ په کښې د رواياتو پابندى کوى، لکه د پيالو، پَتيلو او د تانبې لوښو وينځل دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23349, 'Mark 7:5', 'Mark', 7, 5, '&nbsp;ځکه فريسيانو او د شرعې عالمانو د هغۀ نه دا تپوس وکړو چې، ”ستا مريدان ولې په ناوينځلو لاسونو روټۍ خورى او د مشرانو د رواياتو پابندى نۀ کوى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23350, 'Mark 7:6', 'Mark', 7, 6, '&nbsp;هغۀ جواب ورکړو چې، ”يشعياه نبى ستاسو رياکارانو په حقله په رښتيا سره دا پېشګوئې کړې وه، لکه چې ليکلے شوى دى چې، ”دا خلق تش په خولۀ زما عزت کوى خو زړونه يې زما نه ډېر لرې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
